function validate([matches]) {
  if (!Array.isArray(matches) || matches.length < 1 || matches.length > 100000) return 'matches needs 1 to 10^5 entries.';
  const seen = new Set();
  for (const m of matches) {
    if (!Array.isArray(m) || m.length !== 2) return 'Each match is a [winner, loser] pair.';
    const [w, l] = m;
    if (!Number.isInteger(w) || !Number.isInteger(l) || w < 1 || l < 1 || w > 100000 || l > 100000) return 'Player numbers are between 1 and 10^5.';
    if (w === l) return 'A player cannot play against themselves.';
    const key = w + ',' + l;
    if (seen.has(key)) return 'Each match result appears only once.';
    seen.add(key);
  }
  return null;
}

