function findWinners(matches) {
  const players = [];
  for (const pair of matches) for (const p of pair) if (!players.includes(p)) players.push(p);
  players.sort((a, b) => a - b);
  const result = [[], []];
  for (const p of players) {
    let lost = 0;
    for (const pair of matches) if (pair[1] === p) lost++;
    if (lost < 2) result[lost].push(p);
  }
  return result;
}

