function generate(rand, size) {
  const large = size === 'large';
  const poolSize = large ? 1200 : 2 + Math.floor(rand() * 6);
  const pool = [];
  const used = new Set();
  while (pool.length < poolSize) {
    const id = large ? 1 + Math.floor(rand() * 100000) : 1 + Math.floor(rand() * 12);
    if (!used.has(id)) { used.add(id); pool.push(id); }
  }
  const maxPairs = poolSize * (poolSize - 1);
  const count = large ? 2000 : 1 + Math.floor(rand() * Math.min(10, maxPairs));
  const seen = new Set();
  const matches = [];
  while (matches.length < count) {
    const w = pool[Math.floor(rand() * poolSize)];
    const l = pool[Math.floor(rand() * poolSize)];
    if (w === l || seen.has(w + ',' + l)) continue;
    seen.add(w + ',' + l);
    matches.push([w, l]);
  }
  return [matches];
}
